          ...prev,
          currency: cachedBiz.currency_symbol || cachedBiz.currency_code || '₹',
          tax_rate: fetchedTaxRate,
          business_type: String(cachedBiz.business_category || cachedBiz.business_type || '').toUpperCase().includes('RETAIL') ? 'RETAIL' : 'RESTAURANT'
        }));
