        setPosSettings(prev => ({
          ...prev,
          taxRate: fetchedTaxRate,
          countAdvanceInSales: serverSettings.countAdvanceInSales !== undefined ? !!serverSettings.countAdvanceInSales : prev.countAdvanceInSales
        }));"

